#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <cstring>

int server = socket(AF_INET, SOCK_STREAM, 0);
sockaddr_in adresse{};
adresse.sin_family = AF_INET;
adresse.sin_port = htons(50000);
adresse.sin_addr.s_addr = INADDR_ANY;

bind(server, (sockaddr*)&adresse, sizeof(adresse));
listen(server, 1);

int client = accept(server, nullptr, nullptr);
char puffer[1024];
int n = recv(client, puffer, sizeof(puffer), 0);
send(client, puffer, n, 0);
close(client);
close(server);

